// src/core/root-config/root-config.repository.ts
import { runSystemQuery, runSystemTransaction } from '@core/db';
import type { RootConfigRow, UpdateRootConfigInput } from './root-config.types';

export class RootConfigRepository {
  /**
   * Busca a configuração-raiz (só deve existir uma)
   */
  async find(): Promise<RootConfigRow | undefined> {
    const rows = await runSystemQuery<RootConfigRow>({
      text: `
        SELECT 
          id,
          country_id,
          state_id,
          city_id,
          timezone,
          currency,
          languages,
          created_at,
          updated_at
        FROM root_config
        ORDER BY created_at ASC
        LIMIT 1
      `,
    });
    return rows[0];
  }

  /**
   * Cria ou atualiza a configuração-raiz
   */
  async upsert(input: UpdateRootConfigInput): Promise<RootConfigRow> {
    return runSystemTransaction(async (trx) => {
      // Verifica se já existe
      const existing = await trx.query({
        text: 'SELECT id FROM root_config LIMIT 1',
      });

      if (existing.length > 0) {
        // Atualiza
        const updateFields: string[] = [];
        const values: any[] = [];
        let paramIndex = 1;

        if (input.countryId !== undefined) {
          updateFields.push(`country_id = $${paramIndex}`);
          values.push(input.countryId);
          paramIndex++;
        }
        if (input.stateId !== undefined) {
          updateFields.push(`state_id = $${paramIndex}`);
          values.push(input.stateId);
          paramIndex++;
        }
        if (input.cityId !== undefined) {
          updateFields.push(`city_id = $${paramIndex}`);
          values.push(input.cityId);
          paramIndex++;
        }
        if (input.timezone !== undefined) {
          updateFields.push(`timezone = $${paramIndex}`);
          values.push(input.timezone);
          paramIndex++;
        }
        if (input.currency !== undefined) {
          updateFields.push(`currency = $${paramIndex}`);
          values.push(input.currency);
          paramIndex++;
        }
        if (input.languages !== undefined) {
          updateFields.push(`languages = $${paramIndex}`);
          values.push(input.languages);
          paramIndex++;
        }

        updateFields.push(`updated_at = now()`);
        values.push(existing[0].id);

        const result = await trx.query({
          text: `
            UPDATE root_config
            SET ${updateFields.join(', ')}
            WHERE id = $${paramIndex}
            RETURNING *
          `,
          values,
        });

        return result[0] as RootConfigRow;
      } else {
        // Cria
        const result = await trx.query({
          text: `
            INSERT INTO root_config (
              country_id,
              state_id,
              city_id,
              timezone,
              currency,
              languages
            ) VALUES ($1, $2, $3, $4, $5, $6)
            RETURNING *
          `,
          values: [
            input.countryId ?? null,
            input.stateId ?? null,
            input.cityId ?? null,
            input.timezone ?? null,
            input.currency ?? null,
            input.languages ?? [],
          ],
        });

        return result[0] as RootConfigRow;
      }
    });
  }
}
















